(379, 5860, 7, 'Tune Mill 5 and Mill 6 Boilers', NULL, '2.1133.1', 0, 1000, 1000, 20311, 'Tune 6 boilers in mills 5 and 6 @ $1.000/visit.', 0, 0, 0, NULL, 1000, 20311, '2003-12-01', 0, 'RCM process complete. RCA and Tiger Team processes will be complete by year end.', 1, 0, NULL),
(380, 5861, 8, 'Reduce Air Leaks', NULL, '2.4236.2', 0, 12200, 12200, 12190, 'Reduce leaks in mill 6 from 52>30%.  Use ultra sound gun. that they calibrated by sound level from a tank from which they measured leak rates.', 0, 0, 0, NULL, 12200, 12190, '2003-12-01', 0, 'Measured reductions of $5k in mill 6 so far', 1, 0, NULL),
