(398, 5879, 1, 'Close Buildings 3 & 4', NULL, '4.5210.4', 0, 1920, 1920, 180261, 'Move stored materials to building 1 and rent out buildings 3 and 4. Save $8k in heat + light energy. labor $32k. rent @ $0.50/ft2=140.  IC = 3 people x 40 hours x $16/hr.', 0, 0, 0, NULL, 1920, 180261, '0000-00-00', 6, 'Business changed. added products and lines. need space now', 1, 0, NULL),
(399, 5880, 2, 'Reduce Lighting Level', NULL, '2.7111.14', 0, 530, 530, 9386, 'Disconnect half of 108 400W MH fixtures in over-lit bays 1-3 of building 1.', 0, 0, 0, NULL, 530, 9386, '0000-00-00', 6, 'With production changes. they are now using the assembly space. can\\\'t reduce lighting.', 1, 0, NULL),
(400, 5881, 3, 'Turn off lights after work', NULL, '2.7124.14', 0, 0, 0, 9883, 'Turn off 98 400W MH fixutres in Bays 1.2.4.5 of Building 1 after work hours', 0, 0, 0, NULL, 0, 9883, '2002-09-01', 0, '', 1, 0, NULL),
(401, 5882, 4, 'Build Air Compressor Shed', NULL, '2.4226.1', 0, 5000, 5000, 11195, 'Build an insulated shed for air compressors. which will avoid winterizing the 50 and 75 hp compressors. and allow the 100 hp to turn off.', 0, 0, 0, NULL, 5000, 11195, '2002-09-01', 0, 'Added pipe insulation. now run small compressors in winter. didn\\\'t need shed.', 1, 0, NULL),
