(1040, 6578, 6, 'Remove Light Fixtures', NULL, '271113', 0, 2670, 2670, 9060, 'Turn off half of the metal halide lamps on manufacturing floor.', 0, 0, 0, NULL, 2670, 9060, '2000-03-01', 0, '', 1, 0, NULL),
(1041, 6579, 1, 'Replace Wax With Waxed Carboard', NULL, '413104', 0, 25000, 25000, 530000, 'Use waxed cardboard in place of some of the wood chips and wax in the particle board manufacturing process. This will reduce wax and wood chip costs by 15%.', 0, 0, 0, NULL, 25000, 530000, '0000-00-00', 14, 'Still looking at this recommendation and will get to it down the road. Possibly in 2009.', 1, 0, NULL),
(1042, 6580, 2, 'Increase Refiner Speed', NULL, '241322', 0, 50000, 50000, 42000, 'Increase the speed of the feed side refiner motor from 1200 RPM to 1800 RPM. This measure will decrease total annual electrical energy use by 3.3%.', 0, 0, 0, NULL, 50000, 42000, '2008-01-01', 0, 'Planning to get to it by Jan 2008.  Will be inline for 2008 capital budget.', 1, 0, NULL),
(1043, 6581, 3, 'Reduce Sander Spacing on the Edger/Trimmer', NULL, '411104', 0, 800, 800, 24600, 'Decrease the spacing between boards going into the sander on the edger/trimmer.  This will increase edger/trimmer production capacity by 13%.', 0, 0, 0, NULL, 800, 24600, '0000-00-00', 14, 'The current production bottleneck is the speed of the drop down boxes.  So spacing between the boards hasn\\\'t been addressed yet.', 1, 0, NULL),
(1044, 6582, 4, 'Notched V-belts', NULL, '241112', 0, 0, 0, 13000, 'Replace standard V-belts with higher efficiency notched V-belts on 115 motors.  The use of notched belts has been demonstrated to yield energy savings through reduction of belt losses due to friction. bending. and slippage.', 0, 0, 0, NULL, 0, 13000, '0000-00-00', 8, 'New Maintenance Superintendent isn?t aware of the cost savings.', 1, 0, NULL),
(1045, 6583, 5, 'Reduce Stroke Time', NULL, '411404', 0, 6900, 6900, 13000, 'Divert excess refiner steam to a steam shower on the hardboard press line. This will increase the dry weight percentage of the refined stock. With increasing dryness. press time will decrease. This measure will save total production time by at least 0.2%.', 0, 0, 0, NULL, 6900, 13000, '2007-01-01', 0, 'Budgeted for end of year. They expect higher capital cost ($25K) and higher yield savings ($40K).', 1, 0, NULL),
(1046, 6584, 6, 'Reduce Solid Waste', NULL, '353111', 0, 0, 0, 6360, 'Reduce solid waste expenses by switching to an 8-yd single stream recycling dumpster. This will reduce solid waste disposal and rental fees by approximately 35%.', 0, 0, 0, NULL, 0, 6360, '0000-00-00', 14, 'This fell through the cracks and didn?t get implemented.  After being reminded by the implementation interview they will discuss the idea.', 1, 0, NULL),
(1047, 6585, 7, 'Reduce Setup Time on Edger/Trimmer', NULL, '462504', 0, 40, 40, 5000, 'Reduce time required to changeover the edger/trimmer when changing between hardboard thicknesses.  This will reduce changeover time by 20%.', 0, 0, 0, NULL, 40, 5000, '0000-00-00', 20, '', 1, 0, NULL),
(1048, 6586, 8, 'Increase Paint Recycle Barrel Size', NULL, '372143', 0, 65, 65, 4680, 'In order to avoid loss of paint due to overflow. we recommend that you increase the size of the barrel used to recycle the water-based. latex primer paint back through system. This will save 10 gal/day in paint.', 0, 0, 0, NULL, 65, 4680, '0000-00-00', 6, 'Employess are now supposed to pump down the paint and then flush with water.', 1, 0, NULL),
(1049, 6587, 9, 'Improve Power Factor', NULL, '232111', 0, 3050, 3050, 3350, 'Install 610 kVAR of capacitance to correct for low power factor and reduce power factor penalties by 88%.', 0, 0, 0, NULL, 3050, 3350, '2006-01-01', 0, 'They fixed the connection and capacitors.', 1, 0, NULL);
