(1050, 6588, 10, 'Purchase Automatic Bander', NULL, '444104', 0, 49000, 49000, 25000, 'Purchase an automatic bander to increase production on the edger/trimmer when banding 25-piece stacks of hardboard.  This will decrease the production time needed for these units by 45%.', 0, 0, 0, NULL, 49000, 25000, '2008-01-01', 0, 'Some work complete still in process some technical issues with load handling of sensors.', 1, 0, NULL),
(1051, 6589, 11, 'Install Photosensors to Turn off Exterior Lights', NULL, '271342', 0, 1300, 1300, 2700, 'Install exterior lighting photosensors on 26 exterior lights around the hardboard plant.  This will reduce light energy consumption outside by 50%.', 0, 0, 0, NULL, 1300, 2700, '2008-01-01', 0, 'Working with Energy Trust of Oregon on the Lights.', 1, 0, NULL),
(1052, 6590, 12, 'Insulate DA Tank', NULL, '221232', 0, 1500, 1500, 1800, 'Insulate Deaerator (DA) tank with fiberglass batted insulation and a rigid aluminum cover for protection. This recommendation will reduce energy loss from the tank by 95%.', 0, 0, 0, NULL, 1500, 1800, '2007-01-01', 0, 'Planned but not complete at this time.', 1, 0, NULL),
(1053, 6591, 1, 'Add Embosser to Die Cutter', NULL, '441301', 0, 50000, 50000, 25580, 'In process of building printer. embosser die-cutter in line. New embosser w/manual tension control feeds die-cutter.  Save labor and waste.  Labor to install 360 degrees.', 0, 0, 0, NULL, 50000, 25580, '1999-12-01', 0, '', 1, 0, NULL),
(1054, 6592, 2, 'Change Wood Recyclers', NULL, '361334', 0, 0, 0, 4110, 'Wood hauled by PaC to waste facility - saved ~ 2/3 of OSU estimate.  Reduce disposal costs by 30%', 0, 0, 0, NULL, 0, 4110, '1999-07-01', 0, '', 1, 0, NULL),
(1055, 6593, 3, 'Install Tension Controls', NULL, '441301', 0, 4300, 4300, 16830, 'Implemented AR1 instead.  Save labor .75 FTE of monitoring tensions. Controls on hand.  Build up surplus to install. OT = $700', 0, 0, 0, NULL, 4300, 16830, '0000-00-00', 6, '', 1, 0, NULL),
