(4867, 12465, 3, 'Install Water Atomization', 0, '2.2162', 1, 3535, 1768, 1876, 'Install an atomization system in the kilns. This will eliminate direct steam injection, reducing boiler energy consumption by 7.3%.', 1, 0, 0, 0, 1768, 1876, '0000-00-00', 14, '', 1, 0, 5),
(4868, 12469, 5, 'Convert Hydraulics to Electric Motors', 348, '2.4324', 1, 38393, 24955, 4497, 'Replace the hydraulic pumps and motors used on the conveyor systems in the facility with electric premium efficiency motors. This will increase conveyor system efficiencies by 53% and reduce associated annual energy consumption by 58%.\n', 1, 0, 0, 0, 24955, 4497, '0000-00-00', 14, '', 1, 0, 6),
