(4922, 12712, 6, 'Install Photovoltaic Array', 356, '2.9114', 3, 606368, 340762, 28137, 'Install a photovoltaic array on the building roof. This will provide an alternative energy source for 8% of the facility\'s energy consumption and reduce carbon dioxide emissions associated with electricity generation.\n', 1, 0, 0, 0, 340762, 27514, '0000-00-00', 0, 'Not enough personnel to head this project yet.', 1, 1, 11),
(4923, 12731, 1, 'Repurpose Re-Melt Furnace Area', 0, '3.1161', 1, 669217, 0, 357967, 'Decommision the Re-Melt Furnace and repurpose the area for more productive use. This will increase overall revenues through productivity by 0.4%, and reduce associated annual energy consumption by 100%.', 0, 0, 0, 0, 0, 357967, '0000-00-00', 11, 'not implemented. management resistance - complicate production', 1, 0, 8),
(4924, 12530, 0, 'Install Compressed Air Shut-off Valves', 343, '', 1, 0, 0, 0, '', 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 1, 0, 1),
(4925, 12534, 0, 'Cover Hog Fuel', 353, '', 1, 0, 0, 0, '', 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 1, 0, 0),
